VALUES ('browser-performance', 'Web Performance', 'Web vitals, route change timing, long tasks and page load measured by the Traceway browser SDK', 'browser', '{"schemaVersion":1,"widgets":[{"title":"Largest Contentful Paint (ms)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.lcp","aggregation":"avg","label":"Average"},{"type":"metric","name":"browser.web_vital.lcp","aggregation":"max","label":"Slowest"}]}},{"title":"Interaction to Next Paint (ms)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.inp","aggregation":"avg","label":"Average"},{"type":"metric","name":"browser.web_vital.inp","aggregation":"max","label":"Slowest"}]}},{"title":"Cumulative Layout Shift","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.cls","aggregation":"avg","label":"Average"},{"type":"metric","name":"browser.web_vital.cls","aggregation":"max","label":"Worst"}]}},{"title":"First Contentful Paint (ms)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.fcp","aggregation":"avg","label":"Average"}]}},{"title":"Time to First Byte (ms)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.ttfb","aggregation":"avg","label":"Average"}]}},{"title":"Poor LCP Page Views","widgetType":"bar_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.lcp","aggregation":"count","tagFilters":{"rating":"poor"},"label":"Poor"}]}},{"title":"LCP by Browser (ms)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.lcp","aggregation":"avg","groupBy":"browser.name"}]}},{"title":"Route Change Duration (ms)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.route_timing.duration","aggregation":"avg","label":"Average"},{"type":"metric","name":"browser.route_timing.duration","aggregation":"max","label":"Slowest"}]}},{"title":"Route Change 